.meme-section, .meme-compare, .meme-card { --meme-green: #a2ffb5; color: #f5f5f5; }
.meme-section { border: 1px solid #536158; padding: 16px; margin: 0 0 24px; background: #101411; overflow-wrap: anywhere; }
.meme-eyebrow { display: block; color: var(--meme-green); font: 10px/1.6 "JetBrains Mono", monospace; letter-spacing: .08em; margin: 0 0 12px; }
.meme-section h3, .meme-changes h3 { font-size: 17px; margin: 16px 0 10px; }
.meme-section h3 small { display: block; color: #b8c0ba; font: 10px/1.6 "JetBrains Mono", monospace; font-weight: normal; }
.meme-count { color: var(--meme-green); font: 12px "JetBrains Mono", monospace; }
.meme-note, .meme-date { font-size: 12px; line-height: 1.6; color: #c2c9c3; margin: 10px 0; }
