/* Shill or Chill · Trackdown — v4
   Junction 2026: a Renaissance painting read by machine vision. Black, the painting's own
   colours, white dashed match lines, green detection boxes with scores, a wide wordmark. */
:root {
  --black: #050506;
  --ink-bg: #0b0b0d;
  --surface: #111114;
  --surface-2: #17171b;
  --line: rgba(255, 255, 255, 0.1);
  --line-2: rgba(255, 255, 255, 0.18);
  --line-3: rgba(255, 255, 255, 0.32);
  --text: #f2efe9;
  --text-2: #b4b0a8;
  --text-3: #908c84;
  --text-4: #5c5a55;
  --cv: #3fe07a;
  --cv-2: rgba(63, 224, 122, 0.16);
  /* verdicts + roles, sampled from the painting where possible */
  --shill: #e2533c; /* Flora's rose, pushed */
  --chill: #5fc9a8; /* the sea */
  --unsure: #9aa6bf;
  --origin: #e4b36a; /* Venus's hair, gilded */
  --mutation: #d9783d;
  --amplifier: #e2533c;
  --organic: #5fc9a8;
  --relay: #8f8b84;
  --source: #7aa2f0;
  --submitted: #f2efe9;
  --screenshotted: #b9a6e3; /* the real post a screenshot shows: neutral, not a copy */

  --wide: "Michroma", "Eurostile", ui-sans-serif, sans-serif;
  --sans: "Inter Tight", "Inter", ui-sans-serif, system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, Menlo, monospace;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --cut: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body { margin: 0; background: var(--black); color: var(--text); font: 15px/1.45 var(--sans); -webkit-font-smoothing: antialiased; overflow: hidden; }
button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; padding: 0; }
input, textarea { font: inherit; color: inherit; }
a { color: inherit; }
::selection { background: rgba(63, 224, 122, 0.3); }
.mono { font-family: var(--mono); }
.label { font: 500 11px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-3); }
:focus { outline: none; }
:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
input:focus-visible { outline: none; }
.label::before { content: none; }

.app { display: grid; grid-template-columns: 0px 1fr 0px; grid-template-rows: 60px 1fr; height: 100vh; height: 100dvh; transition: grid-template-columns 0.6s var(--ease-out); }
.app.panel-open { grid-template-columns: 0px 1fr 400px; }
.app .stage { grid-column: 2; grid-row: 2; }
.app .panel { grid-column: 3; grid-row: 2; }
.app:not(.panel-open) .panel { border-left-color: transparent; }
/* calm by default: these appear only when they mean something */
.dock { transition: opacity 0.5s, transform 0.6s var(--ease-out); }
.app:not([data-phase="done"]) .dock { opacity: 0; transform: translateY(24px); pointer-events: none; }
.app:not([data-phase="done"]) .hud { opacity: 0; pointer-events: none; }
.app:not([data-phase="done"]) #badges .vchip { display: none; }
.hud { transition: opacity 0.4s; }
.app:not(.tools) .minimap, .app:not(.tools) .legend { display: none; }
.app.tools .zoom button[data-z="tools"] { color: var(--text); background: var(--surface-2); }
.term { display: none; }
.term.lookup-progress { display: flex; flex-direction: column; }
.lookup-active .st-skip { display: none; }
.lookup-active .panel { border-left-color: var(--line); }
@media (min-width: 860px) {
  .app.lookup-active { grid-template-columns: 0px 1fr 400px; }
}
.term .txt small { display: block; color: var(--text-3); line-height: 1.5; overflow-wrap: anywhere; }
.term [data-state="failed"], .lookup-error { color: var(--shill); }
.term [data-state="pending"], .term [data-state="skipped"] { opacity: .6; }
.lookup-message { color: var(--text-2); font: 400 13px/1.6 var(--sans); white-space: pre-line; }
.receipt-meta { margin: 8px 0; color: var(--text-3); font: 400 11px/1.6 var(--mono); overflow-wrap: anywhere; }
.data-group { margin: 12px 0; padding: 12px; border: 1px solid var(--line); }
.data-group h4 { margin: 0 0 10px; font: 500 13px var(--sans); }
.data-group dl { margin: 0; font: 400 12px/1.6 var(--sans); }
