  .meme-modes { display: none; }
  .meme-comparison[data-view=overlay]:not(:has([data-unavailable])) { height: 270px; }
  .meme-section { padding: 12px; }
}

.meme-finding { margin: 0 0 18px; padding: 12px 14px; border-left: 3px solid var(--vc); background: color-mix(in srgb, var(--vc) 9%, transparent); }
.meme-finding .label { margin-bottom: 6px; }
