/* Shill or Chill · Trackdown — v4
   Junction 2026: a Renaissance painting read by machine vision. Black, the painting's own
   colours, white dashed match lines, green detection boxes with scores, a wide wordmark. */
:root {
  --black: #050506;
  --ink-bg: #0b0b0d;
  --surface: #111114;
  --surface-2: #17171b;
  --line: rgba(255, 255, 255, 0.1);
  --line-2: rgba(255, 255, 255, 0.18);
  --line-3: rgba(255, 255, 255, 0.32);
  --text: #f2efe9;
  --text-2: #b4b0a8;
  --text-3: #908c84;
  --text-4: #5c5a55;
  --cv: #3fe07a;
  --cv-2: rgba(63, 224, 122, 0.16);
  /* verdicts + roles, sampled from the painting where possible */
  --shill: #e2533c; /* Flora's rose, pushed */
  --chill: #5fc9a8; /* the sea */
  --unsure: #9aa6bf;
  --origin: #e4b36a; /* Venus's hair, gilded */
  --mutation: #d9783d;
  --amplifier: #e2533c;
  --organic: #5fc9a8;
  --relay: #8f8b84;
  --source: #7aa2f0;
  --submitted: #f2efe9;
  --screenshotted: #b9a6e3; /* the real post a screenshot shows: neutral, not a copy */

  --wide: "Michroma", "Eurostile", ui-sans-serif, sans-serif;
  --sans: "Inter Tight", "Inter", ui-sans-serif, system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, Menlo, monospace;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --cut: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body { margin: 0; background: var(--black); color: var(--text); font: 15px/1.45 var(--sans); -webkit-font-smoothing: antialiased; overflow: hidden; }
button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; padding: 0; }
input, textarea { font: inherit; color: inherit; }
a { color: inherit; }
::selection { background: rgba(63, 224, 122, 0.3); }
.mono { font-family: var(--mono); }
.label { font: 500 11px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-3); }
:focus { outline: none; }
:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
input:focus-visible { outline: none; }
.label::before { content: none; }

.app { display: grid; grid-template-columns: 0px 1fr 0px; grid-template-rows: 60px 1fr; height: 100vh; height: 100dvh; transition: grid-template-columns 0.6s var(--ease-out); }
.app.panel-open { grid-template-columns: 0px 1fr 400px; }
.app .stage { grid-column: 2; grid-row: 2; }
.app .panel { grid-column: 3; grid-row: 2; }
.app:not(.panel-open) .panel { border-left-color: transparent; }
/* calm by default: these appear only when they mean something */
.dock { transition: opacity 0.5s, transform 0.6s var(--ease-out); }
.app:not([data-phase="done"]) .dock { opacity: 0; transform: translateY(24px); pointer-events: none; }
.app:not([data-phase="done"]) .hud { opacity: 0; pointer-events: none; }
.app:not([data-phase="done"]) #badges .vchip { display: none; }
.hud { transition: opacity 0.4s; }
.app:not(.tools) .minimap, .app:not(.tools) .legend { display: none; }
.app.tools .zoom button[data-z="tools"] { color: var(--text); background: var(--surface-2); }
.term { display: none; }
.term.lookup-progress { display: flex; flex-direction: column; }
.lookup-active .st-skip { display: none; }
.lookup-active .panel { border-left-color: var(--line); }
@media (min-width: 860px) {
  .app.lookup-active { grid-template-columns: 0px 1fr 400px; }
}
.term .txt small { display: block; color: var(--text-3); line-height: 1.5; overflow-wrap: anywhere; }
.term [data-state="failed"], .lookup-error { color: var(--shill); }
.term [data-state="pending"], .term [data-state="skipped"] { opacity: .6; }
.lookup-message { color: var(--text-2); font: 400 13px/1.6 var(--sans); white-space: pre-line; }
.receipt-meta { margin: 8px 0; color: var(--text-3); font: 400 11px/1.6 var(--mono); overflow-wrap: anywhere; }
.data-group { margin: 12px 0; padding: 12px; border: 1px solid var(--line); }
.data-group h4 { margin: 0 0 10px; font: 500 13px var(--sans); }
.data-group dl { margin: 0; font: 400 12px/1.6 var(--sans); }

.data-group dl { margin: 0; font: 400 12px/1.6 var(--sans); }
.data-group dt { color: var(--text-3); margin-top: 7px; }
.data-group dd { margin: 0; overflow-wrap: anywhere; white-space: pre-line; }
.data-group .src { font: 400 11px/1.6 var(--mono); color: var(--source); overflow-wrap: anywhere; }
.platform-x { margin-left: auto; font: 600 20px var(--sans); color: var(--text); }
.card.plat-x { border-top-color: #777; }
.media.source-photo { height: auto; background: none; }
.source-photo img { display: block; width: 100%; max-height: 190px; object-fit: contain; }
.t-bluesky, .ev.t-bluesky { --tc: #6caaff; }

/* ---------- top bar (Junction site) ---------- */
.topbar { grid-column: 1 / -1; display: flex; align-items: center; gap: 22px; padding: 0 16px 0 22px; background: rgba(5, 5, 6, 0.96); border-bottom: 1px solid var(--line); position: relative; z-index: 30; }
.wordmark { text-decoration: none; font: 400 13px/1 var(--wide); letter-spacing: 0.28em; white-space: nowrap; min-width: 256px; text-align: left; }
.wordmark:hover { color: #fff; text-shadow: 0 0 18px rgba(255, 255, 255, 0.35); }
.btn.ghost { border-color: transparent; background: transparent; padding: 0 10px; color: var(--text-2); }
.btn.ghost:hover { color: var(--text); border-color: var(--line-2); }
.case-head { flex: 1; min-width: 0; display: flex; align-items: center; gap: 14px; }
.case-head .label { white-space: nowrap; }
.case-head h1 { margin: 0; font: 600 17px/1.1 var(--sans); letter-spacing: -0.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tag { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; font: 500 11px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase; border: 1px solid currentColor; white-space: nowrap; }
.tag.sim { color: var(--text-2); } .tag.hist { color: #cdb894; }
.vchip { display: inline-flex; align-items: center; gap: 7px; height: 22px; padding: 0 8px; font: 600 11px/1 var(--mono); letter-spacing: 0.14em; color: var(--vc); border: 1px solid var(--vc); white-space: nowrap; }
.vchip::before { content: ""; width: 6px; height: 6px; background: var(--vc); }
.top-actions { display: flex; align-items: center; gap: 10px; }
.trace-wrap { position: relative; display: inline-flex; }
.qr-btn { position: absolute; top: -7px; right: -7px; z-index: 1; width: 18px; height: 14px; display: grid; place-items: center; font: 600 7.5px/1 var(--mono); letter-spacing: 0.04em; color: var(--text-2); background: var(--black); border: 1px solid var(--line-3); }
.qr-btn:hover, .qr-btn:focus-visible { color: var(--text); border-color: var(--text-2); }
.qr-dialog { margin: auto; padding: 18px; background: #08080a; color: var(--text); border: 1px solid var(--line-2); display: grid; justify-items: center; gap: 12px; max-width: calc(100vw - 32px); }
.qr-dialog:not([open]) { display: none; }
.qr-dialog::backdrop { background: rgba(0, 0, 0, 0.7); }
.qr-code { width: min(260px, 70vw); background: #fff; }
.qr-code svg { display: block; width: 100%; height: auto; }
.qr-url { margin: 0; max-width: min(260px, 70vw); font: 400 11px/1.4 var(--mono); color: var(--text-3); word-break: break-all; text-align: center; }
.btn {
  height: 36px; padding: 0 18px; display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  font: 700 11px/1 var(--sans); letter-spacing: 0.14em; text-transform: uppercase; white-space: nowrap;
  color: var(--text); background: var(--black); border: 1px solid var(--line-3);
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.1s;
}
.btn:hover { background: var(--surface-2); border-color: var(--text-2); }
.btn:active { transform: translateY(1px); }
.btn.solid { background: var(--text); color: var(--black); border-color: var(--text); clip-path: var(--cut); }
.btn.solid:focus-visible { clip-path: none; }
.btn.solid:hover { background: #fff; }
.btn.icon { width: 36px; padding: 0; }
.btn svg { width: 14px; height: 14px; }
.btn .kbd { font: 500 9.5px/1 var(--mono); opacity: 0.5; }

.sect span:last-child { margin-left: auto; }
.scrub { outline-offset: 2px; }
.scrub:focus-within { outline: 2px solid var(--text); }
.scrub-range { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; pointer-events: none; margin: 0; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.stage:focus-visible { outline: 2px solid var(--text); outline-offset: -2px; }

/* ---------- stage: the painting under the graph ---------- */
.stage { position: relative; overflow: hidden; cursor: grab; touch-action: none; min-width: 0; background: var(--black); container-type: inline-size; }
/* a narrow stage (tablet with the panel open, phone) gets the dock in two rows: readout, then a full-width scrubber */
@container (max-width: 640px) {
  .stage .dock { height: 118px; grid-template-columns: 1fr; grid-template-rows: auto 1fr; gap: 6px; padding: 8px 10px; }
  .stage .dock .scrub { height: 56px; }
  .stage .dock-right { display: none; }
  .stage .clock { min-width: 0; }
  .stage .hud { bottom: 146px; }
}
.stage.panning { cursor: grabbing; }
.backdrop { position: absolute; inset: -6%; background: var(--black) center / cover no-repeat; opacity: 0.5; filter: brightness(0.34) saturate(0.5); will-change: transform; pointer-events: none; }
.stage canvas.layer { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.world { position: absolute; left: 0; top: 0; width: 0; height: 0; transform-origin: 0 0; }
.vignette { position: absolute; inset: 0; pointer-events: none; z-index: 3; background: radial-gradient(120% 95% at 50% 45%, transparent 45%, rgba(0, 0, 0, 0.78) 100%); }

/* ---------- node cards ---------- */
.card {
  --rc: var(--relay);
  position: absolute; left: 0; top: 0; width: 272px; padding: 12px 13px 10px;
  background: rgba(12, 12, 14, 0.94); border: 1px solid var(--line-2);
  box-shadow: 0 18px 40px -20px rgba(0, 0, 0, 0.95);
  cursor: pointer; user-select: none; transform-origin: 50% 50%;
  opacity: var(--card-op, 1); transition: opacity 0.35s, filter 0.35s, border-color 0.25s, box-shadow 0.25s;
  contain: layout style;
}
.card::before { content: ""; position: absolute; left: -1px; top: -1px; bottom: -1px; width: 2px; background: var(--rc); }
.card.role-origin { --rc: var(--origin); border-color: rgba(228, 179, 106, 0.6); box-shadow: 0 0 50px -12px rgba(228, 179, 106, 0.45), 0 18px 40px -20px #000; }
.card.role-mutation { --rc: var(--mutation); }
.card.role-amplifier { --rc: var(--amplifier); }
.card.role-organic { --rc: var(--organic); }
.card.role-source { --rc: var(--source); }
.card.role-submitted { --rc: var(--submitted); border-color: rgba(242, 239, 233, 0.6); }
.card.role-screenshotted { --rc: var(--screenshotted); border-style: dashed; border-color: rgba(185, 166, 227, 0.55); }
.card:hover { border-color: var(--line-3); }
/* selection = a green detection box around the card */
.card.sel { border-color: var(--cv); box-shadow: 0 0 0 1px var(--cv), 0 0 40px -10px rgba(63, 224, 122, 0.5); }
.card.sel::after { content: "SELECTED"; position: absolute; left: -1px; top: -21px; font: 600 11px/1 var(--mono); letter-spacing: 0.1em; color: #04120a; background: var(--cv); padding: 4px 5px 3px; }
.card.dim { opacity: calc(var(--card-op, 1) * 0.28); filter: grayscale(0.7); }
.card.dragging { z-index: 5; cursor: grabbing; border-color: var(--cv); box-shadow: 0 0 0 1px var(--cv), 0 30px 60px -20px #000; }

.card header { display: flex; align-items: center; gap: 10px; }
.crop { flex: none; width: 30px; height: 30px; background-color: #000; background-repeat: no-repeat; outline: 1.5px solid var(--cv); outline-offset: -1.5px; position: relative; }
.crop.blank { background: repeating-linear-gradient(45deg, #1b1b1f 0 4px, #121215 4px 8px); outline: 1.5px dashed var(--text-3); }
.crop.blank::after { content: "?"; position: absolute; inset: 0; display: grid; place-items: center; font: 600 13px/1 var(--mono); color: var(--text-3); }
.who { min-width: 0; flex: 1; display: flex; flex-direction: column; gap: 2px; }
.who b { font: 600 14px/1.15 var(--sans); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.who span { font: 400 13px/1.2 var(--mono); color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.catno { font: 500 11px/1 var(--mono); color: var(--text-3); align-self: flex-start; white-space: nowrap; }
.rolemark { margin-top: 9px; font: 500 12px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--rc); }

.stamp { position: absolute; right: -1px; top: -21px; font: 600 11px/1 var(--mono); letter-spacing: 0.12em; color: var(--black); background: var(--submitted); padding: 4px 6px 3px; }
.card .txt { margin: 8px 0 0; font: 400 14px/1.45 var(--sans); color: var(--text); display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.card.role-origin .txt { font-size: 15px; }
.flags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px; }
.flag { font: 500 12px/1 var(--mono); letter-spacing: 0.04em; padding: 4px 6px 3px; color: var(--text-2); border: 1px solid var(--line-2); }
.flag.warn { color: #ff9b88; border-color: rgba(226, 83, 60, 0.5); }
.flag.amber { color: #f2b07a; border-color: rgba(217, 120, 61, 0.5); }
.card footer { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed var(--line-2); font: 400 12px/1 var(--mono); color: var(--text-3); white-space: nowrap; }
.card footer .eng { display: inline-flex; align-items: center; gap: 4px; }
.card footer svg { width: 11px; height: 11px; }
.card footer time { margin-left: auto; color: var(--text-2); }

.card.chip { width: 232px; padding: 7px 9px 7px 10px; }
.card.chip header { gap: 8px; }
.card.chip .crop { width: 22px; height: 22px; }
.card.chip .who b { font-size: 15px; }
.card.chip .who span { font-size: 13px; }
.card.chip .chip-meta { display: flex; gap: 8px; align-items: center; margin-top: 5px; font: 400 13px/1 var(--mono); color: var(--text-2); }
.card.chip .chip-meta .age { color: #ff9b88; }
.card.chip .chip-meta time { margin-left: auto; color: var(--text-2); }

/* media */
.media { margin-top: 10px; border: 1px solid var(--line-2); position: relative; overflow: hidden; background: #000; }
.media.link { display: grid; grid-template-columns: 3px 1fr; }
.media.link .thumb { background: var(--rc); }
.media.link .lk { padding: 7px 10px 8px; min-width: 0; }
.media.link .dom { font: 400 13px/1.2 var(--mono); color: var(--text-3); }
.media.link .lt { font: 600 13px/1.3 var(--sans); margin-top: 3px; color: var(--text); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.media.shot { background: #ece7dc; color: #16130e; padding: 10px 12px 12px; }
.media.shot .mast { display: flex; justify-content: space-between; font: 600 8px/1 var(--mono); letter-spacing: 0.14em; color: #6f6551; border-bottom: 2px solid #16130e; padding-bottom: 5px; }
.media.shot .mast .tag2 { color: #b23a1e; }
.media.shot .hl { font: 700 15px/1.15 var(--sans); margin-top: 7px; }
.media.shot .bars { margin-top: 8px; height: 20px; background: repeating-linear-gradient(180deg, #c8bea9 0 2px, transparent 2px 6px); }
.media.shot.cropped .mast { visibility: hidden; height: 0; padding: 0; border: 0; }
.media.photo { height: 96px; background:
  linear-gradient(180deg, transparent 52%, rgba(255, 255, 255, 0.1) 52.5%, transparent 56%),
  repeating-linear-gradient(180deg, transparent 0 7px, rgba(255, 255, 255, 0.07) 7px 8px) 0 52% / 100% 48% no-repeat,
  linear-gradient(90deg, #26313d 0 12%, transparent 12% 18%, #2c3846 18% 30%, transparent 30% 64%, #283340 64% 80%, transparent 80%) 0 0 / 100% 54% no-repeat,
  linear-gradient(180deg, #7d8f9f, #4d6072 54%, #34475a 54%, #1d2a36); }
.media.video { height: 104px; display: grid; place-items: center; background: linear-gradient(180deg, #6c8193 0%, #3e5266 55%, #1a2633 100%); }
.media.video::before { content: ""; position: absolute; left: 0; right: 0; bottom: 30%; height: 9px; background: linear-gradient(90deg, transparent 5%, #15202a 5% 95%, transparent 95%); }
.media .play { width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid #fff; display: grid; place-items: center; position: relative; z-index: 1; }
.media .play::after { content: ""; margin-left: 3px; border-left: 9px solid #fff; border-top: 6px solid transparent; border-bottom: 6px solid transparent; }
.media .cap { position: absolute; left: 8px; bottom: 6px; font: 400 10px/1 var(--mono); color: rgba(255, 255, 255, 0.9); z-index: 1; }
.media.plate { background: #d9cfb6; padding: 5px; }
.media.plate img { display: block; width: 100%; height: 120px; object-fit: cover; object-position: 50% 45%; mix-blend-mode: multiply; filter: sepia(0.2) contrast(1.05); pointer-events: none; }
.media.plate .cap { position: static; display: block; margin-top: 5px; color: #4c4232; font: 400 10.5px/1.2 var(--mono); }
.media-note { margin-top: 7px; font: 400 12px/1.4 var(--mono); color: var(--cv); }
.media-note::before { content: "> "; opacity: 0.7; }

/* detection boxes on media */
.media .cvbox { position: absolute; border: 1.5px solid var(--cv); opacity: 0; transform: scale(1.4); transition: opacity 0.3s, transform 0.45s var(--ease-out); pointer-events: none; z-index: 2; }
.media .cvbox::after { content: ""; position: absolute; inset: 0; background: rgba(63, 224, 122, 0.08); }
.media .cvbox span { position: absolute; left: 0; top: 0; font: 600 10px/1 var(--mono); color: #04120a; background: var(--cv); padding: 2px 3px 1px; white-space: nowrap; }
.card.scanning .media .cvbox, .card.matched .media .cvbox { opacity: 1; transform: none; }
.card.scanning .media .cvbox:nth-of-type(2) { transition-delay: 0.15s; }

/* appear + scan + lock */
.card.enter { animation: card-in 0.6s var(--ease-out) both; }
@keyframes card-in { 0% { opacity: 0; clip-path: inset(0 0 100% 0); } 100% { opacity: var(--card-op, 1); clip-path: inset(0 0 0 0); } }
.card.scanning::after {
  content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 3;
  background: linear-gradient(180deg, transparent 0%, rgba(63, 224, 122, 0) 44%, rgba(63, 224, 122, 0.3) 49.5%, rgba(180, 255, 210, 0.9) 50%, rgba(63, 224, 122, 0) 51%, transparent 100%) 0 0 / 100% 220% no-repeat;
  animation: scan 1.1s linear infinite; outline: 1.5px solid var(--cv);
