@keyframes scan { from { background-position: 0 110%; } to { background-position: 0 -10%; } }
.card.lock { animation: lock 0.7s var(--ease-out); }
@keyframes lock { 0% { outline: 1.5px solid var(--cv); outline-offset: 14px; } 70% { outline: 1.5px solid var(--cv); outline-offset: 0; } 100% { outline: 1.5px solid transparent; } }

/* ---------- stage overlays ---------- */
.ruler { position: absolute; left: 0; right: 0; top: 0; height: 32px; z-index: 6; pointer-events: none; background: linear-gradient(180deg, rgba(5, 5, 6, 0.92), rgba(5, 5, 6, 0)); }
.ruler canvas { width: 100%; height: 100%; display: block; }
.term { position: absolute; left: 16px; top: 44px; z-index: 8; width: 400px; max-width: calc(100% - 32px); max-height: calc(100% - 176px); background: rgba(8, 8, 10, 0.92); border: 1px solid var(--line-2); box-shadow: 0 20px 50px -20px #000; transition: opacity 0.4s, transform 0.5s var(--ease-out); }
.term.hidden { opacity: 0; transform: translateY(-8px); pointer-events: none; }
.term-head { display: flex; align-items: center; gap: 7px; padding: 9px 12px; border-bottom: 1px solid var(--line); font: 400 11px/1 var(--mono); color: var(--text-3); }
.term-head .d { width: 9px; height: 9px; border-radius: 50%; background: #3a3a3e; }
.term-head .d.r { background: #e2533c; } .term-head .d.y { background: #e4b36a; } .term-head .d.g { background: var(--cv); }
.term-head .file { margin-left: 6px; }
.term-head .x { margin-left: auto; font: 500 10px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); }
.term-head .x:hover { color: var(--text); }
.term-body { flex: 1 1 auto; min-height: 0; padding: 10px 14px 12px; overflow: hidden auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: #2a2a2e transparent; font: 400 11.5px/1.6 var(--mono); color: var(--text-2); }
.term-body .cmd { color: var(--text-3); margin-bottom: 6px; }
