content.content:
.btn {
  height: 36px; padding: 0 18px; display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  font: 700 11px/1 var(--sans); letter-spacing: 0.14em; text-transform: uppercase; white-space: nowrap;
  color: var(--text); background: var(--black); border: 1px solid var(--line-3);
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.1s;
}
.card {
  --rc: var(--relay);
  position: absolute; left: 0; top: 0; width: 272px; padding: 12px 13px 10px;
  background: rgba(12, 12, 14, 0.94); border: 1px solid var(--line-2);
  box-shadow: 0 18px 40px -20px rgba(0, 0, 0, 0.95);
  cursor: pointer; user-select: none; transform-origin: 50% 50%;
  opacity: var(--card-op, 1); transition: opacity 0.35s, filter 0.35s, border-color 0.25s, box-shadow 0.25s;
  contain: layout style;
}
.card::before { content: ""; position: absolute; left: -1px; top: -1px; bottom: -1px; width: 2px; background: var(--rc); }

/* media */
.media { margin-top: 10px; border: 1px solid var(--line-2); position: relative; overflow: hidden; background: #000; }
.media.link { display: grid; grid-template-columns: 3px 1fr; }
.media.link .thumb { background: var(--rc); }
.media.link .lk { padding: 7px 10px 8px; min-width: 0; }
.media.link .dom { font: 400 13px/1.2 var(--mono); color: var(--text-3); }
.media.link .lt { font: 600 13px/1.3 var(--sans); margin-top: 3px; color: var(--text); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.media.shot { background: #ece7dc; color: #16130e; padding: 10px 12px 12px; }
.media.shot .mast { display: flex; justify-content: space-between; font: 600 8px/1 var(--mono); letter-spacing: 0.14em; color: #6f6551; border-bottom: 2px solid #16130e; padding-bottom: 5px; }
.media.shot .mast .tag2 { color: #b23a1e; }
.media.shot .hl { font: 700 15px/1.15 var(--sans); margin-top: 7px; }
.media.shot .bars { margin-top: 8px; height: 20px; background: repeating-linear-gradient(180deg, #c8bea9 0 2px, transparent 2px 6px); }
.media.shot.cropped .mast { visibility: hidden; height: 0; padding: 0; border: 0; }
.media.photo { height: 96px; background:
  linear-gradient(180deg, transparent 52%, rgba(255, 255, 255, 0.1) 52.5%, transparent 56%),
  repeating-linear-gradient(180deg, transparent 0 7px, rgba(255, 255, 255, 0.07) 7px 8px) 0 52% / 100% 48% no-repeat,
  linear-gradient(90deg, #26313d 0 12%, transparent 12% 18%, #2c3846 18% 30%, transparent 30% 64%, #283340 64% 80%, transparent 80%) 0 0 / 100% 54% no-repeat,
  linear-gradient(180deg, #7d8f9f, #4d6072 54%, #34475a 54%, #1d2a36); }
.media.video { height: 104px; display: grid; place-items: center; background: linear-gradient(180deg, #6c8193 0%, #3e5266 55%, #1a2633 100%); }
.media.video::before { content: ""; position: absolute; left: 0; right: 0; bottom: 30%; height: 9px; background: linear-gradient(90deg, transparent 5%, #15202a 5% 95%, transparent 95%); }
.media .play { width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid #fff; display: grid; place-items: center; position: relative; z-index: 1; }
.media .play::after { content: ""; margin-left: 3px; border-left: 9px solid #fff; border-top: 6px solid transparent; border-bottom: 6px solid transparent; }
.media .cap { position: absolute; left: 8px; bottom: 6px; font: 400 10px/1 var(--mono); color: rgba(255, 255, 255, 0.9); z-index: 1; }
.media.plate { background: #d9cfb6; padding: 5px; }
.media.plate img { display: block; width: 100%; height: 120px; object-fit: cover; object-position: 50% 45%; mix-blend-mode: multiply; filter: sepia(0.2) contrast(1.05); pointer-events: none; }
.media.plate .cap { position: static; display: block; margin-top: 5px; color: #4c4232; font: 400 10.5px/1.2 var(--mono); }
.media-note { margin-top: 7px; font: 400 12px/1.4 var(--mono); color: var(--cv); }
.media-note::before { content: "> "; opacity: 0.7; }

/* detection boxes on media */
.media .cvbox { position: absolute; border: 1.5px solid var(--cv); opacity: 0; transform: scale(1.4); transition: opacity 0.3s, transform 0.45s var(--ease-out); pointer-events: none; z-index: 2; }
.media .cvbox::after { content: ""; position: absolute; inset: 0; background: rgba(63, 224, 122, 0.08); }
.media .cvbox span { position: absolute; left: 0; top: 0; font: 600 10px/1 var(--mono); color: #04120a; background: var(--cv); padding: 2px 3px 1px; white-space: nowrap; }
.card.scanning .media .cvbox, .card.matched .media .cvbox { opacity: 1; transform: none; }
.panel { background: var(--ink-bg); border-left: 1px solid var(--line); overflow: hidden auto; min-width: 0; position: relative; scrollbar-width: thin; scrollbar-color: #222 transparent; }
.panel-inner { width: 400px; padding: 0 0 40px; }
.win-head { position: sticky; top: 0; z-index: 3; display: flex; align-items: center; background: rgba(11, 11, 13, 0.97); border-bottom: 1px solid var(--line); }
.win-head .tabs { flex: 1; min-width: 0; }
.sheet-close { flex: none; width: 44px; height: 44px; margin-right: 6px; align-items: center; justify-content: center; color: var(--text-2); }
.win-title { display: none; }
.tabs { display: flex; padding: 0 12px; }
.tabs { gap: 4px; }
.tabs button { flex: 1; height: 46px; font: 500 11px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); border-bottom: 1px solid transparent; transition: color 0.2s, border-color 0.2s; }
.tabs button:hover { color: var(--text-2); }
.tabs button.on { color: var(--text); border-bottom-color: var(--text); }
.tabs button .n { color: var(--text-3); margin-left: 6px; }
.pane { padding: 20px 20px 0; animation: line-in 0.35s var(--ease-out); }

.verdict { position: relative; }
.vhead { display: flex; align-items: center; gap: 16px; padding-bottom: 18px; border-bottom: 2px solid var(--vc); }
.vhead .vcoin { flex: none; width: 76px; height: 76px; background-size: cover; filter: drop-shadow(0 8px 12px rgba(0, 0, 0, 0.7)); }
.vhead .vword { font: 400 30px/1 var(--wide); letter-spacing: 0.22em; color: var(--text); }
.vhead .vword.long { font-size: 18px; letter-spacing: 0.14em; line-height: 1.25; }
.verdict .vtag { margin-top: 10px; font: 600 13px/1.2 var(--sans); color: var(--vc); }
