.conf { margin-top: 18px; }
.conf-note { margin-top: 8px; font: 400 12.5px/1.4 var(--sans); color: var(--text-3); }
.conf .row { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
.conf .row b { font: 600 20px/1 var(--sans); color: var(--text); font-variant-numeric: tabular-nums; }
.conf .bar { position: relative; height: 4px; background: var(--line); }
.conf .bar i { position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: var(--vc); transition: width 1.4s var(--ease-out); }
.conf.abstain .bar { background: repeating-linear-gradient(90deg, var(--line-2) 0 4px, transparent 4px 8px); }
.conf.abstain .bar i { display: none; }
.notice { margin-top: 16px; font: 400 13px/1.5 var(--sans); color: var(--text-2); padding: 10px 12px; border: 1px dashed rgba(228, 179, 106, 0.45); }
.notice b { color: var(--origin); font-weight: 600; }
.notice .mono { font-size: 12px; }
.pending .label { display: block; }
.pending p { margin: 10px 0 0; color: var(--text-2); font: 400 15px/1.55 var(--sans); }

.stats { display: grid; grid-template-columns: repeat(3, 1fr); margin-top: 18px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.stat { padding: 14px 4px 12px 14px; border-left: 1px solid var(--line); }
.stat:first-child { border-left: 0; padding-left: 0; }
.stat .n { font: 600 22px/1 var(--sans); color: var(--text); font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.stat .l { margin-top: 8px; font: 500 10.5px/1.2 var(--mono); color: var(--text-3); text-transform: uppercase; letter-spacing: 0.12em; }

.sect { margin: 22px 0 10px; display: flex; gap: 6px; }
.hop { display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; align-items: center; padding: 9px 0; text-align: left; width: 100%; border-bottom: 1px dashed var(--line); transition: background 0.2s; }
.hop:hover .h-t { color: var(--cv); }
.hop .rn { width: 22px; height: 22px; display: grid; place-items: center; font: 500 10px/1 var(--mono); color: var(--c); border: 1.5px solid var(--c); }
.hop .h-t { font: 600 14px/1.2 var(--sans); color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color 0.2s; }
.hop .h-s { font: 400 12px/1.35 var(--sans); color: var(--text-2); margin-top: 2px; }
.hop .h-gap { font: 400 12px/1.35 var(--sans); color: var(--text-2); text-align: right; white-space: nowrap; }
.hop .h-gap b { font-weight: 500; color: var(--text); display: block; }

/* a live update re-renders the same view: no entrance animations, nothing held back */
.panel-inner.quiet .pane, .panel-inner.quiet .ev { animation: none; }
.panel-inner.quiet .conf .bar i { transition: none; }
.term .line.seen { animation: none; }
.ev { padding: 12px 0; border-bottom: 1px solid var(--line); animation: line-in 0.45s var(--ease-out) both; }
.ev .by { display: flex; align-items: center; gap: 7px; font: 500 12px/1.2 var(--sans); color: var(--text-2); }
.ev .by::before { content: ""; width: 7px; height: 7px; flex: none; background: var(--tc); }
.by.t-detector, .ev.t-detector { --tc: #e6e2d8; } .by.t-nemotron, .ev.t-nemotron { --tc: #8fd14f; } .by.t-oxylabs, .ev.t-oxylabs { --tc: #7aa2f0; } .by.t-gemini, .ev.t-gemini { --tc: #b9a3f0; } .by.t-you, .ev.t-you { --tc: #fff; } .by.t-archive, .ev.t-archive { --tc: var(--origin); }
.ev p { margin: 6px 0 0; font: 400 14px/1.5 var(--sans); color: var(--text); }
.ev a.src { display: inline-block; margin-top: 6px; font: 500 12px/1.3 var(--sans); color: var(--source); text-decoration: none; }
.ev a.src:hover { text-decoration: underline; }
.change { font: 400 14px/1.45 var(--sans); color: var(--text-2); padding: 8px 0 8px 22px; position: relative; border-bottom: 1px dashed var(--line); }
.change::before { content: "↺"; position: absolute; left: 2px; color: var(--text-3); }
.nolink { margin-top: 6px; font: 400 12px/1.3 var(--sans); color: var(--text-3); }
.replay { margin-top: 20px; }

.detail { position: relative; }
.detail .close { position: absolute; right: 0; top: 0; width: 32px; height: 32px; display: grid; place-items: center; color: var(--text-3); border: 1px solid var(--line-2); }
.modal-back { position: fixed; inset: 0; z-index: 50; background: rgba(0, 0, 0, 0.72); display: grid; place-items: center; animation: fade 0.3s both; padding: 16px; }
.modal-back.out { animation: fade 0.3s reverse both; }
@keyframes fade { from { opacity: 0; } }
.modal { width: 780px; max-width: 100%; background: var(--ink-bg); border: 1px solid var(--line-2); clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); animation: pop 0.5s var(--ease-out) both; }
@keyframes pop { from { opacity: 0; transform: translateY(14px); } }
.banner { position: relative; height: 210px; overflow: hidden; border-bottom: 1px solid var(--line); background: #000; }
.banner canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.banner .bt { position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); text-align: center; font: 400 38px/1 var(--wide); letter-spacing: 0.32em; text-indent: 0.32em; color: #fff; text-shadow: 0 2px 22px rgba(0, 0, 0, 0.95); pointer-events: none; }
.banner .credit, .vbanner .credit, .reveal .credit { position: absolute; right: 10px; bottom: 8px; font: 400 10.5px/1 var(--mono); color: rgba(255, 255, 255, 0.55); z-index: 4; }
.modal .form { padding: 20px 24px 20px; }
.modal .sub { color: var(--text-2); margin: 0 0 14px; font: 400 15px/1.5 var(--sans); }
.drop { border: 1px solid var(--line-2); padding: 12px; background: #08080a; transition: border-color 0.2s; }
.drop:focus-within, .drop.over { border-color: var(--cv); }
