/* verdict reveal: the Junction banner, full stage, with the verdict as the wordmark */
.reveal { position: absolute; inset: 0; z-index: 20; background: #000; cursor: pointer; animation: fade 0.4s both; }
.reveal.out { animation: fade 0.5s reverse both; }
.reveal canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.reveal .center { position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); text-align: center; pointer-events: none; }
.reveal .coin-slot { position: relative; left: 50%; width: 190px; height: 190px; margin: 95px 0 -80px; background-repeat: no-repeat; filter: drop-shadow(0 22px 22px rgba(0, 0, 0, 0.85)); }
.reveal .meme-slot { display: block; width: auto; height: auto; max-width: min(240px, 60vw); max-height: 200px; margin: 0 auto 30px; object-fit: contain; border: 2px solid var(--vc); background: #000; box-shadow: 0 22px 40px rgba(0, 0, 0, 0.85); opacity: 0; }
