"""Screenshot the Trackdown meme compare dialog + site context. usage: shoot.py <outdir> [port]"""
import os, sys, time
from playwright.sync_api import sync_playwright

OUT = sys.argv[1]; PORT = sys.argv[2] if len(sys.argv) > 2 else "3006"
BASE = f"http://localhost:{PORT}"
os.makedirs(OUT, exist_ok=True)

OPEN = """async ([id, real]) => {
  const { openCompare } = await import('/src/ui/compare.ts');
  const { memeFixture } = await import('/src/data/mockMeme.ts');
  const { lookupCase } = await import('/src/data/lookup.ts');
  const r = memeFixture('meme', location.origin);
  const m = r.image_matches.find(x => x.id === id);
  if (real) {
    // a real photo instead of the flat SVG: the Venus painting on both sides
    const img = location.origin + '/src/assets/venus-full.webp';
    r.posts[0].media_urls = [img]; m.image_url = img; m.thumb_url = img; m.width = 1600; m.height = 1000;
  }
  document.querySelector('dialog.meme-compare')?.close();
  const opener = document.createElement('button'); document.body.append(opener);
  openCompare(lookupCase(r), m, opener);
  await new Promise(res => setTimeout(res, 900));
  return document.querySelector('dialog.meme-compare').scrollHeight;
}"""

with sync_playwright() as p:
    br = p.chromium.launch()
    errs = []
    for name, vw, vh in [("desktop", 1440, 900), ("phone", 390, 844)]:
        pg = br.new_page(viewport={"width": vw, "height": vh})
        pg.on("pageerror", lambda e: errs.append(str(e)))
        # site context: the mock meme lookup with its panel
        pg.goto(f"{BASE}/?mockLookup=meme"); time.sleep(9)
        pg.keyboard.press("Escape"); time.sleep(1.5)
        pg.screenshot(path=f"{OUT}/{name}-site.png")
        for id_, real, tag in [("img:edited", True, "edited"), ("img:cropped", False, "cropped")]:
            pg.evaluate(OPEN, [id_, real])
            pg.screenshot(path=f"{OUT}/{name}-compare-{tag}.png")
            # whole dialog content, scrolled
            pg.evaluate("document.querySelector('dialog.meme-compare').scrollTop = 10000"); time.sleep(0.3)
            pg.screenshot(path=f"{OUT}/{name}-compare-{tag}-bottom.png")
            pg.evaluate("document.querySelector('dialog.meme-compare').scrollTop = 0")
        if name == "desktop":
            pg.evaluate(OPEN, ["img:edited", True])
            pg.click("dialog.meme-compare button[data-view=overlay]"); time.sleep(0.6)
            pg.screenshot(path=f"{OUT}/{name}-compare-overlay.png")
        sw = pg.evaluate("document.documentElement.scrollWidth")
        print(name, "scrollWidth", sw)
        pg.close()
    print("errors:", errs)
    br.close()

