/* Meme trace: the panel section, the canvas cards and the comparison dialog. Same language as the rest of
   Trackdown: near-black surfaces, hairline borders, warm white text, mono labels, Michroma words, the
   painting's colours for meaning and machine-vision green only for detection boxes. */
.meme-section, .meme-compare, .meme-card { color: var(--text); }
.meme-compare { --vc: var(--text); }
.meme-compare[data-relation=edited], .meme-compare[data-relation=cropped] { --vc: var(--mutation); }
.meme-compare[data-relation=same], .meme-compare[data-relation=resized] { --vc: #c9c4bb; }
.meme-compare[data-relation=different], .meme-compare[data-relation=unknown] { --vc: var(--unsure); }
.meme-eyebrow { display: block; margin: 0 0 12px; font: 500 11px/1.4 var(--mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-3); }

/* panel section */
.meme-section { margin: 0 0 24px; padding: 0 0 20px; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
.meme-section h3 { display: flex; align-items: baseline; gap: 10px; margin: 20px 0 10px; font: 600 15px/1.2 var(--sans); }
.meme-section h3 small { font: 500 10.5px/1.2 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); }
.meme-count { font: 500 12px var(--mono); color: var(--text-3); }
.meme-note, .meme-date { margin: 10px 0; font: 400 12.5px/1.5 var(--sans); color: var(--text-3); }
.meme-empty { margin: 10px 0; padding-left: 12px; border-left: 2px solid var(--line-3); font: 400 13px/1.5 var(--sans); color: var(--text-2); }
.meme-failure { padding: 10px 12px; border: 1px dashed rgba(226, 83, 60, 0.55); font: 400 13px/1.5 var(--sans); color: var(--text-2); }
.meme-scanning { padding: 12px; font: 400 12px/1.5 var(--mono); color: var(--cv); border: 1px dashed rgba(63, 224, 122, 0.4); background: repeating-linear-gradient(120deg, rgba(63, 224, 122, 0.06) 0 12px, transparent 12px 24px); }
.meme-group { margin: 14px 0; padding-left: 10px; border-left: 2px solid var(--line-2); }
.meme-group.meme-edited, .meme-group.meme-cropped { border-color: var(--mutation); }
.meme-group h4 { display: flex; justify-content: space-between; margin: 10px 0 8px; font: 500 10.5px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); }
.meme-list-item { display: grid; grid-template-columns: 1fr auto; gap: 4px 8px; width: 100%; padding: 10px 12px; text-align: left; font: 600 14px/1.3 var(--sans); color: var(--text); border: 1px solid var(--line); transition: border-color 0.2s; }
.meme-list-item + .meme-list-item { margin-top: 6px; }
.meme-list-item small { grid-column: 1; font: 400 12px/1.45 var(--sans); color: var(--text-2); }
.meme-list-arrow { grid-column: 2; grid-row: 1 / 3; align-self: center; color: var(--text-3); transition: color 0.2s; }
.meme-list-item:hover { border-color: var(--line-3); }
.meme-list-item:hover .meme-list-arrow { color: var(--text); }
.meme-different { margin: 12px 0; font-size: 12px; color: var(--text-3); }
.meme-different summary { padding: 10px 0; cursor: pointer; font: 500 10.5px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; }
.meme-section :focus-visible, .meme-card :focus-visible, .meme-compare :focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }

/* canvas card */
.card:has(.meme-card) { padding: 0; }
.card:has(.meme-edited) { border-color: rgba(217, 120, 61, 0.6); }
.meme-card { padding: 12px; }
.meme-card .meme-eyebrow { margin-bottom: 6px; font-size: 9.5px; }
.meme-card-open { display: block; width: 100%; padding: 4px 0 10px; text-align: left; }
.meme-card-open strong { display: block; font: 600 16px/1.2 var(--sans); }
.meme-card-preview { display: block; margin-top: 6px; font: 400 11px/1.2 var(--mono); color: var(--text-3); }
.meme-card-open:hover .meme-card-preview { color: var(--text); }
.meme-card a, .meme-compare a { color: var(--text); text-decoration: underline; text-decoration-color: var(--line-3); text-underline-offset: 3px; }
.meme-card a { font: 400 11px var(--mono); }
.meme-card a:hover, .meme-compare a:hover { text-decoration-color: var(--text); }
.meme-card .meme-image { width: 100%; aspect-ratio: var(--ar, 3 / 2); max-height: 220px; overflow: hidden; border: 1px solid var(--line-2); }
.meme-card .meme-image img { object-fit: contain; }
.meme-card .meme-image-fallback { min-height: 0; height: 100%; padding: 8px; font-size: 12px; }

/* image frames */
.meme-image { position: relative; flex: none; max-width: 100%; background: #000; }
.meme-image img { display: block; width: 100%; height: 100%; }
.meme-image img[hidden], .meme-image-fallback[hidden], .meme-slider[hidden] { display: none; }
.meme-image-fallback { display: grid; place-content: center; min-height: 130px; padding: 20px; text-align: center; font: 400 13px/1.5 var(--sans); color: var(--text-2); overflow-wrap: anywhere; }
.meme-image[data-unavailable] .meme-region { display: none; }

/* comparison dialog: the site's modal (cut corners, hairline border) */
.meme-compare { width: min(1080px, calc(100vw - 48px)); max-width: none; max-height: calc(100dvh - 48px); margin: auto; padding: 0; color: var(--text); background: var(--ink-bg); border: 1px solid var(--line-2); clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); overflow: hidden auto; font: 15px/1.45 var(--sans); scrollbar-width: thin; scrollbar-color: #222 transparent; }
.meme-compare[open] { animation: pop 0.5s var(--ease-out) both; }
.meme-compare::backdrop { background: rgba(0, 0, 0, 0.72); backdrop-filter: blur(4px); }
.meme-dialog-head { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin: 0 28px; padding: 24px 0 18px; border-bottom: 2px solid var(--vc); }
.meme-dialog-head .meme-eyebrow { margin: 0 0 12px; }
.meme-dialog-head h2 { margin: 0; font: 400 24px/1.15 var(--wide); letter-spacing: 0.2em; text-transform: uppercase; color: var(--text); }
.meme-close { flex: none; width: 36px; height: 36px; display: grid; place-items: center; color: var(--text-3); border: 1px solid var(--line-2); transition: color 0.2s, border-color 0.2s; }
.meme-close svg { width: 16px; height: 16px; }
.meme-close:hover { color: var(--text); border-color: var(--text-2); }
.meme-compare-body { padding: 4px 28px 28px; }

/* layout switch: the panel's tabs */
.meme-modes { display: flex; gap: 4px; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.meme-modes button { height: 44px; padding: 0 14px; font: 500 11px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); border-bottom: 1px solid transparent; margin-bottom: -1px; transition: color 0.2s, border-color 0.2s; }
.meme-modes button:hover { color: var(--text-2); }
.meme-modes button[aria-pressed=true] { color: var(--text); border-bottom-color: var(--text); }

.meme-comparison { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; position: relative; }
