.meme-plane h3 { position: absolute; top: 0; left: 0; right: 0; z-index: 2; margin: 0; padding: 0 12px; height: 34px; display: flex; align-items: center; font: 500 10.5px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; border-bottom: 1px solid var(--line); background: rgba(11, 11, 13, 0.9); }
.meme-comparison[data-view=overlay] { display: block; height: 380px; }
.meme-comparison[data-view=overlay] .meme-plane { position: absolute; inset: 0; width: 100%; height: 100%; }
.meme-comparison[data-view=overlay] .meme-variant { clip-path: inset(0 calc(100% - var(--reveal)) 0 0); }
.meme-comparison[data-view=overlay] .meme-upload h3 { justify-content: flex-end; }
.meme-comparison[data-view=overlay] .meme-variant h3 { background: none; border-bottom: 0; }
.meme-slider-line { display: none; }
.meme-comparison[data-view=overlay] .meme-slider-line { display: block; position: absolute; left: var(--reveal); top: 0; bottom: 0; z-index: 3; border-left: 1.5px dashed var(--text); pointer-events: none; }
.meme-comparison[data-view=overlay] .meme-slider-line::after { content: ""; position: absolute; top: 50%; left: -8px; width: 14px; height: 14px; background: var(--text); clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); transform: translateY(-50%); }
.meme-comparison[data-view=overlay]:has([data-unavailable]) { display: grid; grid-template-columns: 1fr; height: auto; }
.meme-comparison[data-view=overlay]:has([data-unavailable]) .meme-plane { position: relative; inset: auto; height: 240px; clip-path: none; }
.meme-comparison[data-view=overlay]:has([data-unavailable]) .meme-plane:has([data-unavailable]) { height: 160px; }
.meme-comparison[data-view=overlay]:has([data-unavailable]) .meme-slider-line, .meme-comparison[data-view=overlay]:has([data-unavailable]) + .meme-slider { display: none; }
.meme-slider { display: block; padding: 16px 0 4px; font: 500 10.5px/1 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); }
.meme-slider output { float: right; color: var(--text); font-variant-numeric: tabular-nums; }
.meme-slider input { display: block; width: 100%; min-height: 36px; margin: 6px 0 0; accent-color: var(--text); }

